public static int findNthLeapYear(int Y, int N) {
  if (Y < 1 || N < 1) {
    throw new IllegalArgumentException("Y and N should be positive");
  }
  int leapYears = 0;
  for (int i = Y; i <= Y + N - 1; i++) {
    if (isLeapYear(i)) {
      leapYears++;
      if (leapYears == N) {
        return i;
      }
    }
  }
  return -1;
}

