public static int findLargestSubstring(List<String> strings) {
    // Find the largest string in the list
    String largestString = strings.stream().max(Comparator.comparingInt(String::length)).get();

    // Find the length of the largest string
    int largestLength = largestString.length();

    // Create a set to store the unique characters of the largest string
    Set<Character> uniqueChars = new HashSet<>();
    for (char c : largestString.toCharArray()) {
        uniqueChars.add(c);
    }

    // Iterate over the list of strings and check if any of them contain the unique characters of the largest string
    for (String s : strings) {
        if (s.contains(new String(uniqueChars.toArray()))) {
            return largestLength;
        }
    }

    // If no string contains the unique characters, return 0
    return 0;
}

