public static int countOilDeposits(char[][] grid) {
    // Initialize a hash set to store the oil deposits
    Set<String> oilDeposits = new HashSet<>();

    // Iterate over each row of the grid
    for (int i = 0; i < grid.length; i++) {
        // Iterate over each column of the grid
        for (int j = 0; j < grid[i].length; j++) {
            // If the current cell is an oil pocket, add it to the hash set
            if (grid[i][j] == '@') {
                oilDeposits.add(i + "-" + j);
            }

            // If the current cell is not an oil pocket, check if it is adjacent to an oil pocket
            else if (grid[i][j] != '*') {
                // Check if the current cell is adjacent to the top of the grid
                if (i > 0 && grid[i - 1][j] == '@') {
                    oilDeposits.add(i - 1 + "-" + j);
                }

                // Check if the current cell is adjacent to the bottom of the grid
                if (i < grid.length - 1 && grid[i + 1][j] == '@') {
                    oilDeposits.add(i + 1 + "-" + j);
                }

                // Check if the current cell is adjacent to the left of the grid
                if (j > 0 && grid[i][j - 1] == '@') {
                    oilDeposits.add(i + "-" + j - 1);
                }

                // Check if the current cell is adjacent to the right of the grid
                if (j < grid[i].length - 1 && grid[i][j + 1] == '@') {
                    oilDeposits.add(i + "-" + j + 1);
                }
            }
        }
    }

    // Return the size of the hash set
    return oilDeposits.size();
}

