public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if the start and end points are valid
    if (start.length != 2 || end.length != 2) {
        throw new IllegalArgumentException("Start and end points must be 2-dimensional");
    }

    // Check if the paths array is valid
    if (paths.length != n) {
        throw new IllegalArgumentException("Paths array must have the same size as the n-dimension");
    }

    // Initialize the visited array
    boolean[] visited = new boolean[n];

    // Add the starting point to the queue
    Queue<int[]> queue = new LinkedList<>();
    queue.add(start);

    // BFS search
    while (!queue.isEmpty()) {
        int[] current = queue.poll();

        // Check if we have reached the ending point
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        // Mark the current point as visited
        visited[current[0] * n + current[1]] = true;

        // Add the neighboring points to the queue
        for (int[] path : paths) {
            if (!visited[path[0] * n + path[1]] && path[0] == current[0] && path[1] == current[1]) {
                queue.add(path);
            }
        }
    }

    // If we reach here, we couldn't find a path from the starting point to the ending point
    return "cannot be travelled";
}

