public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if start and end points are valid
    if (start[0] < 0 || start[1] < 0 || end[0] >= n || end[1] >= n) {
        return "cannot be travelled";
    }

    // Initialize a boolean array to keep track of visited n-tersections
    boolean[] visited = new boolean[n * n];
    Arrays.fill(visited, false);

    // Use a queue to perform BFS search
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);
    visited[start[0] * n + start[1]] = true;

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        // Check for adjacent n-tersections
        for (int[] path : paths) {
            int[] next = new int[2];
            next[0] = current[0] + path[0];
            next[1] = current[1] + path[1];
            if (next[0] < 0 || next[1] < 0 || next[0] >= n || next[1] >= n) {
                continue;
            }
            if (!visited[next[0] * n + next[1]]) {
                visited[next[0] * n + next[1]] = true;
                queue.offer(next);
            }
        }
    }

    return "cannot be travelled";
}

