public static String appx(String word1, String word2) {
    // Initialize variables to store the number of common letters and the sum of the lengths of the words
    int commonLetters = 0;
    int sumOfLengths = 0;

    // Loop through each character in the first word
    for (int i = 0; i < word1.length(); i++) {
        // Check if the character is present in the second word
        if (word2.contains(word1.charAt(i))) {
            // If it is, increment the number of common letters
            commonLetters++;
        }
    }

    // Add the lengths of the two words
    sumOfLengths = word1.length() + word2.length();

    // Return the reduced fraction of the number of common letters and the sum of the lengths
    return "" + commonLetters + "/" + sumOfLengths;
