public int[] twoSum(int[] nums, int target) {
    // Create a hash map to store the indices of the elements in the array
    Map<Integer, Integer> map = new HashMap<>();

    // Loop through the array and add each element to the hash map
    for (int i = 0; i < nums.length; i++) {
        map.put(nums[i], i);
    }

    // Loop through the array again and find the elements that add up to the target
    for (int i = 0; i < nums.length; i++) {
        int complement = target - nums[i];
        if (map.containsKey(complement) && map.get(complement) != i) {
            return new int[] {i, map.get(complement)};
        }
    }

    // If no elements add up to the target, return an empty array
    return new int[] {};
}

