public int search(int[] nums, int target) {
    // Edge case: if the array has only one element, the target cannot be found
    if (nums.length == 1) {
        return target == nums[0] ? 0 : -1;
    }

    // Find the pivot index
    int pivot = findPivot(nums);

    // If the pivot is at the beginning of the array, search in the first half of the array
    if (pivot == 0) {
        return binarySearch(nums, target, 0, pivot - 1);
    }

    // If the pivot is at the end of the array, search in the second half of the array
    if (pivot == nums.length - 1) {
        return binarySearch(nums, target, pivot + 1, nums.length - 1);
    }

    // Search in both halves of the array
    int left = binarySearch(nums, target, 0, pivot - 1);
    int right = binarySearch(nums, target, pivot + 1, nums.length - 1);

    // Return the index of the target value if found, otherwise -1
    return left != -1 ? left : right;
}

