public int maxUniqueSplit(String s) {
    // Initialize a hash map to keep track of the unique substrings
    Map<String, Integer> uniqueSubstrings = new HashMap<>();

    // Iterate over the characters in the input string
    for (int i = 0; i < s.length(); i++) {
        // Get the current character
        char c = s.charAt(i);

        // Iterate over the remaining characters in the input string
        for (int j = i + 1; j < s.length(); j++) {
            // Get the substring starting from the current character and ending at the next character
            String substring = s.substring(i, j + 1);

            // If the substring is already in the hash map, it means we've seen it before, so skip it
            if (uniqueSubstrings.containsKey(substring)) {
                continue;
            }

            // Check if the substring is unique by checking if it is a substring of the original string
            if (s.contains(substring)) {
                // Add the substring to the hash map if it is unique
                uniqueSubstrings.put(substring, 1);
            }
        }
    }

    // Return the size of the hash map, which is the maximum number of unique substrings
    return uniqueSubstrings.size();
}

