        for (int i = 0; i < Math.min(aa.length(), bb.length()); i++) {
            if (aa.charAt(i) < bb.charAt(i)) {
                return -1;
            }
            if (aa.charAt(i) > bb.charAt(i)) {
                return 1;
            }
        }
        return aa.length() - bb.length();
    });
    return result;
}

